const items = $input.all().map(i => i.json.item).filter(Boolean);
const list = items.length ? items.join(', ') : '(nothing currently marked stocked)';
const text = `Household Ledger check-in 📋

Currently stocked: ${list}

`
  + `Reply in this format (either line optional, or reply NONE if nothing changed):
`
  + `LOW: item, item
FINISHED: item, item`;
return [{ json: { text } }];

// Payload posted by the Reply Listener workflow's Call Resume Webhook node.
const body = $input.first().json || {};
return [{ json: { lowItems: body.lowItems || [], finishedItems: body.finishedItems || [] } }];

// Computes the Inventory row updates for items marked low/finished in the reply,
// including the running avg_days_to_finish per architecture.md Section 6 step 4.
const { lowItems, finishedItems } = $('Read Parsed Reply').first().json;
const rows = $input.all().map(i => i.json);
const byItem = new Map(rows.map(r => [r.item, r]));
const today = DateTime.now().toFormat('yyyy-MM-dd');
const updates = [];

for (const name of lowItems) {
  const row = byItem.get(name);
  if (!row) continue;
  updates.push({ item: name, status: 'low', last_purchased_date: row.last_purchased_date,
                 last_finished_date: row.last_finished_date, avg_days_to_finish: row.avg_days_to_finish,
                 cycle_count: row.cycle_count });
}

for (const name of finishedItems) {
  const row = byItem.get(name);
  if (!row) continue;
  const purchased = row.last_purchased_date ? DateTime.fromFormat(String(row.last_purchased_date), 'yyyy-MM-dd') : null;
  const daysElapsed = purchased && purchased.isValid ? DateTime.now().diff(purchased, 'days').days : null;
  const prevAvg = Number(row.avg_days_to_finish) || null;
  const prevCycles = Number(row.cycle_count) || 0;
  // Simple running average, same style as BNS's recency-window logic.
  const newAvg = daysElapsed == null ? prevAvg
    : (prevAvg == null ? daysElapsed : ((prevAvg * prevCycles) + daysElapsed) / (prevCycles + 1));
  updates.push({ item: name, status: 'finished', last_purchased_date: row.last_purchased_date,
                 last_finished_date: today, avg_days_to_finish: newAvg ? Math.round(newAvg * 10) / 10 : '',
                 cycle_count: prevCycles + 1 });
}

return updates.map(u => ({ json: u }));

// Auto-adds newly low/finished items to ShoppingList, per architecture.md Section 6 step 5.
// Picks the cheapest store per item, same logic as bestStore() in src/App.jsx, kept in
// sync manually for now (not shared code between the app and this workflow).
const { lowItems, finishedItems } = $('Read Parsed Reply').first().json;
const names = [...new Set([...lowItems, ...finishedItems])];
const catalogRows = $input.all().map(i => i.json);

const rowsForItem = (name) => catalogRows.filter(r => r.item === name);

const additions = [];
for (const name of names) {
  const rows = rowsForItem(name);
  if (!rows.length) continue; // not in Catalog — skip rather than add a priceless row
  const cheapest = rows.reduce((a, b) => (Number(b.price) < Number(a.price) ? b : a));
  additions.push({
    item: name,
    category: cheapest.category,
    store: cheapest.store,
    price: cheapest.price,
    qty: 1,
  });
}
return additions.map(a => ({ json: a }));
